/**
 * nginx 采集段的合成夹具 —— 供解析器单测使用。
 *
 * 结构照真机（一台机器上 6 个站点、只有一个在用的反代是 nginx），
 * **域名与 IP 全部换成 example.com / 10.x**，不含任何真实主机信息。
 *
 * 刻意覆盖的形态，每一条都是真机上真实出现过的：
 *   - 同一域名的 80 跳转块 + 443 业务块（必须合并成一条，否则界面上重复）
 *   - `location = /stats {` 与 `location /stats/ {` 两种写法
 *   - location 里带量词的正则：`….{8,}\.(js|css)$` —— 花括号计数法在这种行上必错
 *   - `proxy_pass https://…`（上游自己也走 TLS）
 *   - `proxy_pass http://10.99.0.2:30400`：上游不在本机，端口恰好在 NodePort 段
 *   - `proxy_pass http://backend;`：只有 upstream 名，解析不到端口
 *   - `server_name _;` 默认站点：不是可访问域名
 *   - conf.d 里只有 map、没有 server 块
 *   - sites-available 里的 .bak 备份：**未启用，必须忽略**
 *   - `#` 注释行、行尾注释、引号内的 `#`
 */
export const NGINX_SECTION = [
  '@@FILE /etc/nginx/nginx.conf',
  'user www-data;',
  'worker_processes auto;',
  'events {',
  '    worker_connections 768;',
  '}',
  'http {',
  '    sendfile on;',
  '    include /etc/nginx/conf.d/*.conf;',
  '    include /etc/nginx/sites-enabled/*;',
  '}',
  '@@END',
  '@@FILE /etc/nginx/conf.d/connection-upgrade.conf',
  '# WebSocket 升级映射（没有 server 块，只提供变量）',
  'map $http_upgrade $connection_upgrade {',
  "    default upgrade;",
  "    ''      close;",
  '}',
  '@@END',
  '@@FILE /etc/nginx/conf.d/performance.conf',
  'gzip on;',
  'gzip_types text/plain text/css application/json;   # 行尾注释',
  'ssl_protocols TLSv1.2 TLSv1.3;',
  '@@END',
  '@@FILE /etc/nginx/sites-enabled/site-default',
  'server {',
  '    listen 80 default_server;',
  '    server_name _;',
  '    return 444;',
  '}',
  '@@END',
  '@@FILE /etc/nginx/sites-enabled/site-blog',
  'server {',
  '    listen 80;',
  '    listen [::]:80;',
  '    server_name blog.example.com www.blog.example.com;',
  '    return 301 https://$host$request_uri;',
  '}',
  '',
  'server {',
  '    listen 443 ssl http2;',
  '    listen [::]:443 ssl http2;',
  '    server_name blog.example.com www.blog.example.com;',
  '',
  '    ssl_certificate /etc/nginx/ssl/blog.example.com_bundle.crt;',
  '    ssl_certificate_key /etc/nginx/ssl/blog.example.com.key;',
  '',
  '    client_max_body_size 64m;',
  '    proxy_buffering off;',
  '',
  '    location = /stats {',
  '        return 301 /stats/;',
  '    }',
  '',
  '    # 访问统计：上游是一个本机 Python 进程',
  '    location /stats/ {',
  '        proxy_pass http://127.0.0.1:8099;',
  '        proxy_http_version 1.1;',
  '        proxy_set_header Host $host;',
  '    }',
  '',
  '    location / {',
  '        proxy_pass http://127.0.0.1:30001;',
  '        proxy_http_version 1.1;',
  '        # if 块是 location 内部的嵌套结构，不能让它的 `}` 提前结束 location',
  '        if ($request_method = POST) {',
  '            proxy_set_header X-Body yes;',
  '        }',
  '        proxy_set_header Host $http_host;',
  '        proxy_set_header X-Forwarded-Proto https;',
  '        proxy_set_header Upgrade $http_upgrade;',
  '        proxy_set_header Connection $connection_upgrade;',
  '    }',
  '',
  '    location ~* "^/static/[^?]+\\.[0-9a-f]{8,}\\.(js|css|svg|png|woff2?)$" {',
  '        proxy_pass http://127.0.0.1:30001;',
  '        expires 7d;',
  '        add_header Cache-Control "public, immutable" always;  # 含 # 的引号无妨',
  '    }',
  '}',
  '@@END',
  '@@FILE /etc/nginx/sites-enabled/site-rancher',
  'server {',
  '    listen 80;',
  '    listen [::]:80;',
  '    server_name rancher.example.com;',
  '    return 301 https://$host$request_uri;',
  '}',
  '',
  'server {',
  '    listen 443 ssl http2;',
  '    listen [::]:443 ssl http2;',
  '    server_name rancher.example.com;',
  '',
  '    ssl_certificate /etc/nginx/ssl/rancher.example.com_bundle.crt;',
  '    ssl_certificate_key /etc/nginx/ssl/rancher.example.com.key;',
  '',
  '    client_max_body_size 1g;',
  '    proxy_read_timeout 900s;',
  '',
  '    location / {',
  '        proxy_pass https://127.0.0.1:8443;',
  '        proxy_ssl_verify off;',
  '        proxy_http_version 1.1;',
  '        proxy_set_header Host $host;',
  '    }',
  '}',
  '@@END',
  '@@FILE /etc/nginx/sites-enabled/site-oss-api',
  'server {',
  '    listen 443 ssl;',
  '    server_name oss.example.com;',
  '    location / {',
  '        proxy_pass http://127.0.0.1:30900;',
  '    }',
  '}',
  '@@END',
  '@@FILE /etc/nginx/sites-enabled/site-oss-console',
  'server {',
  '    listen 443 ssl;',
  '    server_name oss-console.example.com;',
  '    location / {',
  '        proxy_pass http://127.0.0.1:30901;',
  '    }',
  '    location ~* "^/static/[^?]+\\.[0-9a-f]{8,}\\.(js|css)$" {',
  '        proxy_pass http://127.0.0.1:30901;',
  '    }',
  '}',
  '@@END',
  '@@FILE /etc/nginx/sites-enabled/site-gateway',
  '# 上游是集群 NodePort，只监听容器网段，不直接暴露到公网',
  'server {',
  '    listen 443 ssl http2;',
  '    server_name llm.example.com;',
  '    location = / {',
  '        return 302 /ui/;',
  '    }',
  '    location / {',
  '        proxy_pass http://10.99.0.2:30400;',
  '        proxy_set_header Host $http_host;',
  '    }',
  '}',
  '@@END',
  '@@FILE /etc/nginx/sites-enabled/site-internal',
  'upstream internal_api {',
  '    server 127.0.0.1:9000;',
  '}',
  '',
  'server {',
  '    listen 8443 ssl;',
  '    server_name internal.example.com;',
  '    location / {',
  '        proxy_pass http://internal_api;',
  '    }',
  '}',
  '@@END',
  '@@FILE /etc/nginx/sites-available/site-blog.bak-20260101',
  'server {',
  '    listen 443 ssl;',
  '    server_name old.example.com;',
  '    location / {',
  '        proxy_pass http://127.0.0.1:9999;',
  '    }',
  '}',
  '@@END'
].join('\n')

/** 期望从上面那份配置里得到的域名清单（按主域名码点升序 —— 这就是界面上会看到的顺序） */
export const VHOST_EXPECTED = {
  /** 备份文件里的 old.example.com 不该出现 */
  primaryNames: [
    'blog.example.com',
    'internal.example.com',
    'llm.example.com',
    // 码点序里 `-`(0x2D) 小于 `.`(0x2E)，所以 oss-console 排在 oss 前面
    'oss-console.example.com',
    'oss.example.com',
    'rancher.example.com'
  ],
  /** 默认站点 `server_name _;` 不算域名 */
  ignoredNames: ['_', 'old.example.com']
} as const
